const TAU=Math.PI*2,polar=(p,l,a)=>({x:p.x+l*Math.cos(a),y:p.y+l*Math.sin(a)}),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export const arthropodSpecs={spider:{body:[36,29],abdomen:[-31,-42,51,40],lengths:[4,5,22,5,21,13,7],stride:9,lift:14,scale:1.9,clips:['idle','walk','run','jump','threat','groom','extend']},scorpion:{body:[41,24],abdomen:[-25,-32,60,30],y:-32,hipY:-28,lengths:[3,3,15,3,12,8,5],legTiles:[5,5,2,11,2,11,4],targets:[-40,-19,27,46],stride:6,lift:5,scale:1.9,claws:true,tail:[20,18,17,16,14],clips:['idle','walk','run','pinch','sting','guard','tail','extend']}};
export const arthropodMotions={idle:['呼吸待机',2,true],walk:['八足行走',1.2,true],run:['八足快跑',.75,true],jump:['跳跃',1.3,false],threat:['抬腿警戒',1.6,false],groom:['触肢梳理',1.8,false],pinch:['双螯夹击',1.1,false],sting:['尾刺攻击',1.3,false],guard:['举螯警戒',1.5,false],tail:['尾链摆动',1.4,true],extend:['单关节屈伸',1,true]};
const segmentNames=['基节','转节','股节','膝节','胫节','跖节','跗节'];
export function arthropodDesign(a){return {title:a.name+' · 多关节运动',assembly:'七节步足保留稳定身份和连接关系。近远腿分别遮挡；圆弧零件自然重叠，不显示机械轴点。',actions:a.clips.map(id=>{const [name,duration,loop]=arthropodMotions[id];return {id,name,duration,loop,keyPoses:id==='threat'?['准备','抬起前腿','警戒','放回']:id==='jump'?['蓄力','腾空','缓冲','回位']:['中性','关节协同','回位'],participants:a.parts.filter(p=>p.id!=='root').map(p=>p.id),timing:'完整动作独立时长；单关节屈伸只带动下游零件。',ranges:'逐关节固定骨长；七节步足采用迭代逆运动学。',contact:'行走四足组交替支撑，支撑端世界坐标固定。',acceptance:['七节长度稳定','逐关节连接','八腿参与','无支撑滑动','末首连续']};}),visualReview:['检查远近遮挡','逐帧看足尖及接缝','检查警戒前腿和梳理触肢'],limitations:['二维侧面运动学；不替代生物动力学、丝线或地面摩擦仿真。']};}
export function createArthropod(id,options={}){const s=arthropodSpecs[id];if(!s)throw Error('多关节角色尚未完成');const size=options.size??1,stride=options.stride??s.stride,color=options.color??'#e1a34c';if(!Number.isFinite(size)||size<.65||size>1.35||!Number.isFinite(stride)||stride<4||stride>55||!/^#[0-9a-f]{6}$/i.test(color))throw Error('参数无效');const parts=[],make=(id,name,parent,shape,rest,dimensions,layer,tile,extra={})=>parts.push({id,name,parent,shape,rest,dimensions,layer,tile,material:color,...extra});make('root','装配原点',null,'anchor',[0,0],[0,0],0,0);make('body','头胸部','root','ellipse',[5,s.y??-42],s.body,3,1);make('abdomen','腹部','body','ellipse',s.abdomen.slice(0,2),s.abdomen.slice(2),3,0);make('pedicel','腹柄','body','bone',[-10,-42],[12,5],2,id==='scorpion'?14:9,{role:'pedicel'});
