if(!s.claws)for(let i=0;i<2;i++){make(`palp-${i}-0`,'触肢上段','body','bone',[20,-40],[11,5],i?2:6,10,{role:'palp',arm:i,segment:0});make(`palp-${i}-1`,'触肢下段',`palp-${i}-0`,'bone',[0,0],[10,4],i?2:6,11,{role:'palp',arm:i,segment:1});make(`fang-${i}`,'螯牙','body','bone',[22,-39],[7,5],i?2:6,12+i,{role:'fang',arm:i});}
if(s.claws){for(let i=0;i<2;i++){make(`claw-${i}-upper`,'螯肢 · 上段','body','bone',[23,-33],[16,7],i?2:6,7,{role:'claw-upper',arm:i});make(`claw-${i}-lower`,'螯肢 · 前臂',`claw-${i}-upper`,'bone',[0,0],[16,6],i?2:6,8,{role:'claw-lower',arm:i});make(`claw-${i}-palm`,'螯掌固定指',`claw-${i}-lower`,'bone',[0,0],[20,10],i?2:6,9,{role:'claw-palm',arm:i});make(`claw-${i}-finger`,'活动螯指',`claw-${i}-palm`,'bone',[0,0],[12,4],i?2:6,i?12:10,{role:'claw-finger',arm:i});}for(let j=0;j<s.tail.length;j++)make('tail-'+j,'尾链 '+(j+1),j?'tail-'+(j-1):'abdomen','bone',[-50,-33],[s.tail[j],10-j*.6],4,6,{role:'tail-chain',segment:j,skinHeight:10-j*.6});make('stinger','尾刺','tail-4','bone',[0,0],[13,9],4,13,{role:'stinger'});}
const a={schemaVersion:1,id:id+'-side-v2',species:id,name:presets.find(p=>p.id===id).name,version:2,design:{color,size,stride,view:'侧面 · 正交 · 朝右'},parts,clips:s.clips,status:'draft',qa:{technical:'untested',visual:'pending'},source:{kind:'redrawn-rounded-part-atlas',description:'侧面七节步足，圆弧端部及内部轴点'},rendering:{rig:'arthropod-side-v2',atlas:`/art/${id}-side-parts-v2.png`,view:'side',projection:'orthographic',facing:'right',frame:{anchor:[256,350],scale:s.scale}}};if(id==='scorpion'){a.id='scorpion-side-v3';a.version=3;}a.actionDesign=arthropodDesign(a);return a;}
export function validateArthropod(a){if(!a||a.schemaVersion!==1||!arthropodSpecs[a.species]||!Array.isArray(a.parts))throw Error('无效资产');const expected=createArthropod(a.species,a.design).parts;if(a.parts.length!==expected.length)throw Error('零件数量不完整');for(const e of expected){const p=a.parts.find(p=>p.id===e.id);if(!p||p.parent!==e.parent||p.role!==e.role||p.leg!==e.leg||p.segment!==e.segment||p.tile!==e.tile||!p.dimensions.every(x=>Number.isFinite(x)&&x>=0&&x<200))throw Error('零件身份或尺寸无效');}return a;}
export function solveChain(hip,target,ls,bend=1,arch=30){const total=ls.reduce((n,l)=>n+l,0),d=dist(hip,target),points=[{...hip}];let length=0;for(const l of ls){length+=l;const f=length/total;points.push({x:hip.x+(target.x-hip.x)*f+bend*12*Math.sin(f*Math.PI),y:hip.y+(target.y-hip.y)*f-arch*Math.sin(f*Math.PI)});}const at=(a,b,l)=>{const d=dist(a,b)||1;return {x:b.x+(a.x-b.x)/d*l,y:b.y+(a.y-b.y)/d*l};};if(d>=total){for(let i=1;i<points.length;i++)points[i]=polar(points[i-1],ls[i-1],Math.atan2(target.y-hip.y,target.x-hip.x));return points;}for(let k=0;k<100;k++){points[ls.length]={...target};for(let i=ls.length-1;i>=0;i--)points[i]=at(points[i],points[i+1],ls[i]);points[0]={...hip};for(let i=1;i<=ls.length;i++)points[i]=at(points[i],points[i-1],ls[i-1]);if(dist(points.at(-1),target)<.000001)break;}return points;}
